<?php\n\nsession_start();\n\necho \"=== Página de Logout ===\\n\\n\";\n\necho \"Dados da sessão antes de destruir:\\n\";\nif (!empty(\$_SESSION)) {\n    foreach (\$_SESSION as \$chave => \$valor) {\n        echo \"- \$_SESSION['\" . \$chave . \"'] = '\" . \$valor . \"'\\n\";\n    }\n} else {\n    echo \"Sessão vazia\\n\";\n}\n\necho \"\\n\";\n\n// Destruir a sessão\necho \"Destruindo sessão com session_destroy()...\\n\";\nsession_destroy();\n\n\$_SESSION = array();\n\necho \"\\nApós logout:\\n\";\necho \"- Sessão foi destruída\\n\";\necho \"- \$_SESSION foi zerado\\n\";\necho \"- Usuário deslogado\\n\";\n\necho \"\\nSe acessar novamente:\\n\";\necho \"- Será criada uma nova sessão (novo ID)\\n\";\necho \"- Dados anteriores não existem mais\\n\";\necho \"- Usuário não estará autenticado\\n\";\n\necho \"\\n--- Diferença: require_once vs include ---\\n\";\necho \"require_once: se já incluiu, não inclui de novo + gera erro se não existir\\n\";\necho \"include: pode incluir múltiplas vezes + aviso se não existir\\n\";\necho \"\\nUsamos require_once em autenticação porque é crítico!\\n\";\n\n?>"
